UPDATE dtb_customer
SET email=JSON_VALUE(:customer, '$.email'), password=JSON_VALUE(:customer, '$.passwordHash'), name01=JSON_VALUE(:customer, '$.name01'), name02=JSON_VALUE(:customer, '$.name02'), kana01=JSON_VALUE(:customer, '$.kana01'), kana02=JSON_VALUE(:customer, '$.kana02'), company_name=JSON_VALUE(:customer, '$.companyName'), phone_number=JSON_VALUE(:customer, '$.phoneNumber'), postal_code=JSON_VALUE(:customer, '$.postalCode'), pref_id=CAST(JSON_VALUE(:customer, '$.pref') AS UNSIGNED), addr01=JSON_VALUE(:customer, '$.addr01'), addr02=JSON_VALUE(:customer, '$.addr02'), birth=JSON_VALUE(:customer, '$.birth'), sex_id=CAST(JSON_VALUE(:customer, '$.sex') AS UNSIGNED), job_id=CAST(JSON_VALUE(:customer, '$.job') AS UNSIGNED), customer_status_id=CAST(JSON_VALUE(:customer, '$.customerStatus') AS UNSIGNED), secret_key=COALESCE(JSON_VALUE(:customer, '$.secretKey'), ''), point=CAST(JSON_VALUE(:customer, '$.initialPoint') AS SIGNED), update_date=NOW()
WHERE JSON_VALUE(:customer, '$.customerId') REGEXP '^[0-9]+$' AND id=CAST(JSON_VALUE(:customer, '$.customerId') AS UNSIGNED)
